  "\" /></label>\n        <button class=\"primary-button compare-go\" data-action=\"sync-plan-start\"><svg><use href=\"#i-play\"/></svg>生成差异计划</button>\n      </div>\n      <div id=\"sync-results\" class=\"compare-results\">": "\" /></label>\n        <button class=\"primary-button compare-go\" data-action=\"sync-plan-start\"><svg><use href=\"#i-play\"/></svg>Generate Diff Plan</button>\n      </div>\n      <div id=\"sync-results\" class=\"compare-results\">",
